import { DisabledAdminActions } from "@/components/admin/disabled-actions";
import { DataTable, EmptyState, PageHeader } from "@/components/portal/page-header";
import { requireRole } from "@/lib/auth/access";
import { getPrisma } from "@/lib/db";

export const dynamic = "force-dynamic";
export default async function VendorManagementPage() { await requireRole(["ADMIN", "SUPER_ADMIN"]); const vendors = await getPrisma().membership.findMany({ where: { role: "VENDOR" }, include: { organization: { include: { profile: true } } }, orderBy: { createdAt: "desc" }, take: 100 }); return <section><PageHeader eyebrow="Directory" title="Vendor Management"/><label className="mt-8 block max-w-md"><span className="sr-only">Search for a vendor</span><input className="w-full rounded-xl border border-[var(--line)] bg-white px-4 py-3" type="search" placeholder="Search for a user" disabled/></label><DataTable columns={["Vendor", "Vendor ID", "WhatsApp", "Actions"]}>{vendors.map((vendor) => <tr key={vendor.id}><td className="px-5 py-4 font-bold">{vendor.organization.profile?.displayName ?? vendor.organization.name}</td><td className="px-5 py-4 font-mono text-xs">{vendor.authUserId}</td><td className="px-5 py-4">{vendor.organization.profile?.whatsapp ?? "—"}</td><td className="px-5 py-4"><DisabledAdminActions subject="Vendor"/></td></tr>)}</DataTable>{!vendors.length && <div className="rounded-b-[1.25rem] border-x border-b border-[var(--line)] bg-white"><EmptyState title="No vendors" description="Vendor memberships will appear here after registration."/></div>}</section>; }
